#include <iostream>
struct Rate {
    int multiplier;
    int apply(int n) const { return multiplier * n; }
};
class Report {
    Rate rate_;

  public:
    explicit Report(Rate r) : rate_(r) {}
    int total(int n) const { return rate_.apply(n); }
};
int main() {
    Report r{Rate{3}};
    std::cout << r.total(4) << '\n';
}

