#include <memory>
struct Rule {
    virtual int apply(int n) const = 0;
    virtual ~Rule() = default;
};
struct Regular final : Rule {
    int apply(int n) const override { return n; }
};
struct Urgent final : Rule {
    int apply(int n) const override {
        // TODO: Реализуйте правило срочного режима в допустимом диапазоне
        // n.
        return 0;
    }
};
int main() {
    int mode, n;
    if (!(std::cin >> mode >> n) || mode < 0 || mode > 1 || n < 0 ||
        n > 100) {
        std::cout << "invalid\n";
        return 0;
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) {
        std::cout << "invalid\n";
        return 0;
    }
    std::unique_ptr<Rule> r = std::make_unique<Regular>();
    // TODO: Выберите конкретного владельца по mode, сохранив базовый
    // интерфейс.
    std::cout << r->apply(n) << ' '
              << (dynamic_cast<Urgent *>(r.get()) != nullptr) << '\n';
}
